-- ============================================
-- 步骤3: 组装输出（UP × 日期 粒度）
-- 注意：用FULL OUTER JOIN确保GMV和VV都有数据的日期都出现
-- ============================================
SELECT
    up_id,
    dt AS `日期`,
    SUM(gmv) AS `gmv`,
    SUM(vv) AS `vv`
FROM (
    SELECT up_id, dt, daily_gmv AS gmv, 0 AS vv FROM charge_daily
    UNION ALL
    SELECT up_id, dt, 0 AS gmv, daily_vv AS vv FROM vv_daily
) t
GROUP BY up_id, dt